/**
 * Salesforce Node - Version 1.1
 * Discriminator: resource=lead, operation=addNote
 */


interface Credentials {
  salesforceOAuth2Api: CredentialReference;
  salesforceJwtApi: CredentialReference;
}

/** Represents a prospect or potential */
export type SalesforceV11LeadAddNoteParams = {
  resource: 'lead';
  operation: 'addNote';
/**
 * OAuth Authorization Flow
 * @default oAuth2
 */
    authentication?: 'oAuth2' | 'jwt' | Expression<string>;
/**
 * ID of lead that needs to be fetched
 */
    leadId: string | Expression<string>;
/**
 * Title of the note
 */
    title: string | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Body of the note. Limited to 32 KB.
     */
    body?: string | Expression<string>;
    /** Whether true, only the note owner or a user with the “Modify All Data” permission can view the note or query it via the API
     * @default false
     */
    isPrivate?: boolean | Expression<boolean>;
    /** The user who owns the note
     * @searchListMethod searchUsers
     * @default {"mode":"list","value":""}
     */
    owner?: { __rl: true; mode: 'list' | 'id'; value: string; cachedResultName?: string };
  };
};

export type SalesforceV11LeadAddNoteOutput = {
  id?: string;
  success?: boolean;
};

export type SalesforceV11LeadAddNoteNode = {
  type: 'n8n-nodes-base.salesforce';
  version: 1.1;
  config: NodeConfig<SalesforceV11LeadAddNoteParams> & { credentials?: Credentials };
  output?: Items<SalesforceV11LeadAddNoteOutput>;
};